(()=>{
 const q=s=>document.querySelector(s),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let meta={},user,currentTable='assets',recordRows=[],submitHandler,cache={};
 const title=s=>s.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
 async function api(path,method='GET',body){const r=await fetch(path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===401){location.replace('/login');throw Error('Please sign in.');}const d=await r.json();if(!r.ok)throw Error(d.message||'Request failed.');return d;}
 async function data(t){if(!cache[t])cache[t]=(await api('/api/records/'+t+'?limit=500')).rows;return cache[t];}
 function label(row,t){return row[`${t.replace(/s$/,'')}_name`]||row.asset_tag||row.employee_number&&`${row.employee_number} · ${row.first_name} ${row.last_name}`||row.username||row.location_name||row.vendor_name||row.type_name||row.model_name||row.category_name||row.class_name||row.status_name||row.condition_name||row.profile_name||row.session_name||row.original_filename||Object.values(row).slice(0,3).join(' · ');}
 const auto=new Set(['created_at','updated_at','created_by','updated_by','uploaded_at','uploaded_by','last_login_at','failed_login_count','locked_until','password_hash','mfa_enabled']);
 const enumOptions={scope_type:['ENTERPRISE','BUSINESS_UNIT','SITE','DEPARTMENT','COST_CENTER','SELF'],access_level:['VIEW','MANAGE'],assignment_status:['ACTIVE','RETURNED','CANCELLED'],movement_status:['REQUESTED','APPROVED','IN_TRANSIT','COMPLETED','CANCELLED'],warranty_status:['ACTIVE','EXPIRED','UNKNOWN','VOID'],repair_source:['IN_HOUSE','THIRD_PARTY'],document_type:['INVOICE','PO','WARRANTY','PHOTO','REPAIR_REPORT','DATA_WIPE_CERT','DISPOSAL_CERT','ASSIGNMENT_FORM','GATE_PASS','OTHER'],device_type:['PHONE','TABLET','DESKTOP']};
 async function field(c,value,table){const required=c.null==='NO',name=c.name;let control;
  if(c.references){let options=[];try{options=await data(c.references[0]);}catch{}control=`<select name="${name}" ${required?'required':''}><option value="">Select…</option>${options.map(row=>`<option value="${escape(row[c.references[1]])}" ${String(value)===String(row[c.references[1]])?'selected':''}>${escape(label(row,c.references[0]))}</option>`).join('')}</select>`;}
  else if(c.type==='BOOLEAN')control=`<select name="${name}"><option value="1" ${Number(value??(['mfa_enabled','is_read','flagged','data_wipe_confirmed'].includes(name)?0:1))===1?'selected':''}>Yes</option><option value="0" ${Number(value)===0?'selected':''}>No</option></select>`;
  else if(enumOptions[name])control=`<select name="${name}" ${required?'required':''}>${!required?'<option value="">Select…</option>':''}${enumOptions[name].map(v=>`<option ${v===value?'selected':''}>${v}</option>`).join('')}</select>`;
  else if(['TEXT','JSON'].includes(c.type))control=`<textarea name="${name}" rows="3" ${required?'required':''}>${escape(value||'')}</textarea>`;
  else control=`<input name="${name}" value="${escape(value??(name==='quantity'?'1':''))}" type="${c.type==='DATE'?'date':c.type==='DATETIME'?'datetime-local':name==='password'?'password':['INT','BIGINT'].includes(c.type)?'number':'text'}" ${c.type.startsWith('DECIMAL')?'inputmode="decimal"':''} ${required?'required':''} ${name==='password'?'minlength="8" autocomplete="new-password"':''}>`;
  return `<label>${escape(title(name))}${required?' *':''}${control}<span class="field-hint">${escape(c.description||'')}</span></label>`;
 }
 async function dialog(name,cols,values,handler){q('#cloud-dialog-title').textContent=name;q('#cloud-fields').innerHTML='<p>Loading form…</p>';q('#cloud-error').hidden=true;q('#cloud-dialog').showModal();submitHandler=handler;q('#cloud-fields').innerHTML=(await Promise.all(cols.map(c=>field(c,values?.[c.name],currentTable)))).join('');}
 const idOf=row=>meta[currentTable].columns.filter(c=>c.key.includes('PK')).map(c=>row[c.name]).join(',');
 async function loadRecords(){q('#records-table').textContent='Loading records…';q('#module-title').textContent=title(currentTable);q('#new-record').hidden=!meta[currentTable]?.editable;try{recordRows=(await api('/api/records/'+currentTable+'?q='+encodeURIComponent(q('#cloud-search').value))).rows;const cols=meta[currentTable].columns.filter(c=>!auto.has(c.name)).slice(0,8);q('#records-table').innerHTML=recordRows.length?`<div class="table-scroll"><table class="records-data-table" role="table"><thead><tr>${cols.map(c=>`<th scope="col">${escape(title(c.name))}</th>`).join('')}<th scope="col">Actions</th></tr></thead><tbody>${recordRows.map((row,i)=>`<tr>${cols.map(c=>`<td data-label="${escape(title(c.name))}"><span>${escape(row[c.name]??'—')}</span></td>`).join('')}<td data-label="Actions"><div class="record-actions"><button data-record-view="${i}">${currentTable==='assets'?'Open asset':'View'}</button>${meta[currentTable].editable?`<button data-record-edit="${i}">Edit</button>`:''}${currentTable==='files'?`<a href="/api/files/${row.file_id}">Download</a>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><b>No records found.</b><p>Add a record or try another search.</p></div>';}catch(e){q('#records-table').textContent=e.message;}}
 async function dashboard(){try{const d=await api('/api/dashboard');q('#cloud-stats').innerHTML=[{status_name:'Total Assets',count:d.counts.reduce((n,s)=>n+Number(s.count),0)},...d.counts].map(s=>`<div><b>${s.count}</b><span>${escape(s.status_name)}</span></div>`).join('');q('#cloud-recent').innerHTML=d.recent.length?d.recent.map(a=>`<div class="row"><div><b>${escape(a.asset_tag)}</b><p>${escape(a.description||'')} · ${escape(a.status_name)} · ${escape(a.location_name||'Location not set')}</p></div><button data-open-asset="${a.asset_id}">Open</button></div>`).join(''):'<div class="empty"><b>No registered assets yet.</b><p>Register assets in Asset Management. Add your locations and employees before assigning custody.</p></div>';}catch(e){q('#cloud-stats').textContent=e.message;}}
 async function recordForm(row){const cols=meta[currentTable].columns.filter(c=>!auto.has(c.name)&&!(c.key==='PK')&&!(row&&c.key.includes('PK'))&&!(currentTable==='assets'&&['status_id','current_location_id'].includes(c.name)&&row)&&!(currentTable==='assets'&&c.name==='status_id'));if(currentTable==='users')cols.push({name:'password',type:'VARCHAR(256)',null:row?'YES':'NO',description:row?'Leave blank to keep the existing password.':'Initial password.'});const t=currentTable,key=row?idOf(row):'';await dialog(row?'Edit '+title(t):'New '+title(t),cols,row,async d=>{await api('/api/records/'+t+(row?'/'+key:''),row?'PATCH':'POST',d);cache={};await loadRecords();await dashboard();});}
 const f=(name,ref,required=true)=>({name,type:ref?'BIGINT':'VARCHAR(500)',null:required?'NO':'YES',references:ref});
 const actions={assign:[f('employee_id',['employees','employee_id']),f('location_id',['locations','location_id']),{name:'expected_return_date',type:'DATE',null:'YES'},f('notes',null,false)],return:[f('location_id',['locations','location_id']),f('notes',null,false)],transfer:[f('location_id',['locations','location_id']),f('notes',null,false)],receive:[],repair:[f('repair_source'),f('vendor_id',['vendors','vendor_id'],false),f('issue_description')],'repair-return':[f('location_id',['locations','location_id']),{name:'repair_cost',type:'DECIMAL(18,2)',null:'YES'},f('notes',null,false)],refresh:[f('notes')],'disposal-request':[f('disposal_method_id',['disposal_methods','disposal_method_id']),{name:'data_wipe_required',type:'BOOLEAN',null:'NO'},f('notes',null,false)],'disposal-approve':[],'disposal-complete':[f('certificate_file_id',['files','file_id']),{name:'data_wipe_confirmed',type:'BOOLEAN',null:'NO'}],depreciate:[{name:'period_date',type:'DATE',null:'NO',description:'First day of the month (YYYY-MM-01).'}]};
 async function asset(id){q('#asset-dialog').showModal();q('#asset-content').textContent='Loading…';try{const a=(await api('/api/records/assets/'+id)).rows[0];if(!a)throw Error('Asset unavailable.');q('#asset-title').textContent=a.asset_tag;const histories=['asset_assignments','asset_movements','asset_repairs','asset_refreshes','asset_disposals','asset_depreciation','asset_files'];let sections='';for(const t of histories){if(!meta[t])continue;const list=(await api('/api/records/'+t+'?limit=500')).rows.filter(r=>String(r.asset_id)===String(id));sections+=`<details><summary>${title(t)} (${list.length})</summary><pre>${escape(JSON.stringify(list,null,2))}</pre></details>`;}const permitted=name=>user.super||user.permissions.includes(`${name==='depreciate'?'finance':/repair|refresh|dispos/.test(name)?'support':'assets'}.manage`);q('#asset-content').innerHTML=`<dl class="record-values">${Object.entries(a).map(([k,v])=>`<dt>${title(k)}</dt><dd>${escape(v??'—')}</dd>`).join('')}</dl><div class="asset-actions">${Object.keys(actions).filter(permitted).map(name=>`<button data-asset-action="${name}" data-asset-id="${id}">${title(name.replaceAll('-',' '))}</button>`).join('')}${user.super||user.permissions.includes('files.manage')?`<button data-upload-asset="${id}">Upload evidence</button>`:''}${user.super||user.permissions.includes('security.manage')?`<button data-security-asset="${id}">Gate check</button>`:''}</div>${sections}`;}catch(e){q('#asset-content').textContent=e.message;}}
 window.mdmCloudScan=async barcode=>{try{const d=await api('/api/scan','POST',{barcode,inventory_session_id:q('#scan-session').value||null,location_id:q('#scan-location').value||null,device_type:matchMedia('(max-width: 700px)').matches?'PHONE':'DESKTOP'});q('#cloud-scan-result').innerHTML=`<p><strong>${escape(d.result)}</strong> ${d.asset?escape(d.asset.asset_tag):'No registered asset matches this barcode.'} ${d.asset?`<button data-open-asset="${d.asset.asset_id}">Open asset</button>`:''}</p>`;}catch(e){q('#cloud-scan-result').textContent='Shared scan was not saved: '+e.message;}};
 q('#cloud-form').onsubmit=async e=>{e.preventDefault();const button=q('#cloud-save');button.disabled=true;q('#cloud-error').hidden=true;try{const d=Object.fromEntries(new FormData(e.target));for(const [k,v]of Object.entries(d)){if(v==='')delete d[k];else if(meta[currentTable]?.columns.find(c=>c.name===k)?.type==='DATETIME')d[k]=new Date(v).toISOString();}await submitHandler(d);q('#cloud-dialog').close();}catch(error){q('#cloud-error').textContent=error.message;q('#cloud-error').hidden=false;}finally{button.disabled=false;}};
 q('#cloud-close').onclick=()=>q('#cloud-dialog').close();q('#asset-close').onclick=()=>q('#asset-dialog').close();q('#new-record').onclick=()=>recordForm();q('#refresh-records').onclick=()=>{cache={};loadRecords();};q('#module-select').onchange=()=>{currentTable=q('#module-select').value;q('#cloud-search').value='';loadRecords();};let timer;q('#cloud-search').oninput=()=>{clearTimeout(timer);timer=setTimeout(loadRecords,350);};
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
  if(b.dataset.page==='records')loadRecords();if(b.dataset.page==='dashboard')dashboard();if(b.dataset.recordEdit!==undefined)await recordForm(recordRows[Number(b.dataset.recordEdit)]);
  if(b.dataset.recordView!==undefined){const row=recordRows[Number(b.dataset.recordView)];if(currentTable==='assets')await asset(row.asset_id);else{q('#asset-title').textContent=title(currentTable);q('#asset-content').innerHTML=`<pre>${escape(JSON.stringify(row,null,2))}</pre>`;q('#asset-dialog').showModal();}}
  if(b.dataset.openAsset)await asset(b.dataset.openAsset);
  if(b.dataset.assetAction){const id=b.dataset.assetId,action=b.dataset.assetAction;await dialog(title(action.replaceAll('-',' ')),actions[action],{},async d=>{if('data_wipe_confirmed'in d)d.data_wipe_confirmed=d.data_wipe_confirmed==='1';if('data_wipe_required'in d)d.data_wipe_required=d.data_wipe_required==='1';await api(`/api/assets/${id}/actions/${action}`,'POST',d);cache={};await asset(id);await dashboard();});}
  if(b.dataset.securityAsset){const id=b.dataset.securityAsset;await dialog('Security gate check',[{name:'movement_type',type:'VARCHAR(50)',null:'NO',description:'ENTRY or EXIT'},f('gate_pass_id',['gate_passes','gate_pass_id'],false),f('employee_id',['employees','employee_id'],false),f('location_id',['locations','location_id'],false),f('notes',null,false)],{},async d=>{const r=await api('/api/security/check','POST',{asset_id:id,...d});alert(r.result);});}
  if(b.dataset.uploadAsset){const id=b.dataset.uploadAsset;await dialog('Upload evidence',[{name:'document_type',type:'VARCHAR(50)',null:'NO'}],{},async d=>{const file=q('#evidence-file').files[0];if(!file)throw Error('Select a file.');if(file.size>5242880)throw Error('Maximum file size is 5 MB.');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});await api('/api/files','POST',{asset_id:id,...d,filename:file.name,mime_type:file.type,base64});cache={};await asset(id);});q('#cloud-fields').insertAdjacentHTML('beforeend','<label>File (up to 5 MB)<input id="evidence-file" type="file" required></label>');}
 }catch(error){alert(error.message);}});
 q('#import-local').onclick=async()=>{const records=typeof inventory!=='undefined'?inventory:[];if(!records.length){alert('No device inventory to import.');return;}await dialog('Import '+records.length+' device items',[f('category_id',['asset_categories','category_id']),f('asset_type_id',['asset_types','asset_type_id']),f('asset_class_id',['asset_classes','asset_class_id']),f('condition_id',['asset_conditions','condition_id']),f('current_location_id',['locations','location_id'],false)],{},async d=>{let count=0;for(const r of records){try{await api('/api/records/assets','POST',{...d,asset_tag:r.assetTag||r.barcode,barcode:r.barcode,serial_number:r.serialNumber||null,description:r.itemName||r.description||null,quantity:String(r.quantity||1),is_serialized:Number(r.quantity||1)===1?1:0});count++;}catch(e){throw Error(`${count} imported. Item ${r.barcode}: ${e.message}. Device records remain available.`);}}cache={};await loadRecords();await dashboard();});};
 (async()=>{try{const result=await api('/api/metadata');meta=result.tables;user=result.user;q('#account-role').textContent=user.roles.join(', ').replaceAll('_',' ');q('#module-select').innerHTML=Object.entries(meta).sort(([a],[b])=>a==='assets'?-1:b==='assets'?1:a.localeCompare(b)).map(([t,m])=>`<option value="${t}">${title(m.module)} · ${title(t)}</option>`).join('');q('#module-select').value='assets';q('#import-local').hidden=!user.super;await dashboard();if(meta.inventory_sessions){const sessions=await data('inventory_sessions');q('#scan-session').innerHTML+=sessions.filter(s=>s.status==='ACTIVE').map(s=>`<option value="${s.inventory_session_id}">${escape(s.session_name)}</option>`).join('');if(meta.locations){q('#scan-location').innerHTML+=(await data('locations')).map(l=>`<option value="${l.location_id}">${escape(l.location_name)}</option>`).join('');}} }catch(e){q('#cloud-stats').textContent=e.message;}})();
})();
